  </span>
</label>
<div style="border-top:1px solid #ddd;margin-top:4px;padding-top:4px;font-weight:bold;">Demo steps</div>
<button data-step="0">a) Original image</button>
<button data-step="1">b) 4×4 windows</button>
<button data-step="2">c) 4×4 offset windows</button>
<button data-step="3">d) 2×2 windows</button>
<button data-step="4">e) 2×2 offset windows</button>
<button data-step="5">f) 1×1 window</button>
<div style="font-size:10px;color:#555;max-width:170px;">Click a tile to see the self-attention computed among its tokens. Drag to reveal the true 3D slab.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// photo base      → BoxGeometry(4, 4.5, 0.5) grey slab; depth recedes +Z so oblique shear shows tilted edge
// mural tiles     → PlaneGeometry per window, CanvasTexture (stylized graffiti), sub-UVs, white gaps
// grid lines      → thin black Box strips raised above tile surface
// clicked tile    → translucent orange plane + orange border strips
// tokens          → 4×4 dark-blue CircleGeometry dots inside clicked tile
// attention lines → LineSegments, semi-transparent blue, all token pairs within tile
// dimmed others   → translucent grey plane over non-selected tiles
// panel label     → addLabel centered below plane

const W = 4, H = 4.5, GAP = 0.03, ZLINE = 0.56, ZTILE = 0.52, SLAB_D = 0.5;
let N = 4, offsetMode = false, plainMode = false;

/* ── Stylized graffiti mural texture ── */
function makeMuralTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 512;
  const g = c.getContext('2d');
  g.fillStyle = '#96958f'; g.fillRect(0, 0, 512, 512);
  for (let i = 0; i < 900; i++) {
    g.fillStyle = `rgba(${60 + Math.random() * 60 | 0},${60 + Math.random() * 60 | 0},${55 + Math.random() * 55 | 0},0.12)`;
    g.fillRect(Math.random() * 512, Math.random() * 512, 2 + Math.random() * 4, 2 + Math.random() * 4);
  }
  g.fillStyle = '#5a5a52'; g.fillRect(0, 0, 512, 34);
  g.fillStyle = '#7a8a3a';
  for (let i = 0; i < 60; i++) g.fillRect(Math.random() * 512, Math.random() * 26, 6 + Math.random() * 14, 3 + Math.random() * 5);
  for (let i = 0; i < 26; i++) {
    g.fillStyle = ['rgba(150,60,140,0.55)', 'rgba(90,60,120,0.5)', 'rgba(200,80,120,0.5)'][i % 3];
    g.beginPath(); g.arc(300 + Math.random() * 200, 40 + Math.random() * 300, 2 + Math.random() * 7, 0, 7); g.fill();
  }
  g.fillStyle = '#1c1c1e';
  g.beginPath(); g.ellipse(200, 190, 72, 92, 0, 0, 7); g.fill();
  g.fillStyle = '#e8a0b8';
  g.beginPath(); g.ellipse(205, 200, 46, 56, 0, 0, 7); g.fill();
  g.fillStyle = '#1c1c1e';
  g.beginPath(); g.ellipse(200, 158, 52, 30, 0, Math.PI, 0); g.fill();
  g.strokeStyle = '#222'; g.lineWidth = 3;
  g.strokeRect(178, 190, 22, 16); g.strokeRect(212, 190, 22, 16);
  g.beginPath(); g.moveTo(200, 198); g.lineTo(212, 198); g.stroke();
  g.beginPath(); g.arc(206, 222, 12, 0.2, Math.PI - 0.2); g.stroke();
  g.fillStyle = '#e8c81e';
  g.beginPath();
  g.moveTo(140, 300); g.quadraticCurveTo(205, 260, 270, 300);
  g.lineTo(285, 460); g.lineTo(125, 460); g.closePath(); g.fill();
  g.strokeStyle = '#b89a10'; g.lineWidth = 3; g.stroke();
  g.fillStyle = '#d8b812';
  g.beginPath(); g.ellipse(205, 285, 46, 20, 0, 0, 7); g.fill();
  g.fillStyle = '#333';
  g.beginPath(); g.moveTo(196, 300); g.lineTo(214, 300); g.lineTo(205, 312); g.closePath(); g.fill();
  g.save(); g.translate(70, 330); g.rotate(-0.12);
  g.fillStyle = '#f2f0ea'; g.fillRect(-55, -80, 100, 150);
  g.strokeStyle = '#888'; g.lineWidth = 2; g.strokeRect(-55, -80, 100, 150);
  g.strokeStyle = '#c02030'; g.lineWidth = 3;
  for (let r = 0; r < 4; r++) {
    g.beginPath();
    let x = -45, y = -60 + r * 32;
    g.moveTo(x, y);
    while (x < 35) { x += 8 + Math.random() * 8; g.lineTo(x, y + (Math.random() * 14 - 7)); }
    g.stroke();
  }
  g.restore();
  g.save(); g.translate(390, 210); g.rotate(0.10);
  g.fillStyle = '#f2f0ea'; g.fillRect(-70, -90, 130, 170);
  g.strokeStyle = '#888'; g.lineWidth = 2; g.strokeRect(-70, -90, 130, 170);
  g.strokeStyle = '#c02030'; g.lineWidth = 3;
  for (let r = 0; r < 5; r++) {
    g.beginPath();
    let x = -58, y = -70 + r * 32;
    g.moveTo(x, y);
    while (x < 48) { x += 8 + Math.random() * 8; g.lineTo(x, y + (Math.random() * 14 - 7)); }
    g.stroke();
  }
  g.restore();
  function heart(x, y, s) {
    g.fillStyle = '#c02535';
    g.beginPath();
    g.moveTo(x, y + s);
    g.bezierCurveTo(x - s * 1.4, y, x - s * 0.7, y - s, x, y - s * 0.3);
    g.bezierCurveTo(x + s * 0.7, y - s, x + s * 1.4, y, x, y + s);
    g.fill();
  }
  heart(60, 120, 16); heart(455, 330, 14); heart(330, 430, 12);
  g.strokeStyle = '#2a9aa0'; g.lineWidth = 4;
  g.beginPath(); g.moveTo(430, 60); g.quadraticCurveTo(470, 90, 445, 130); g.stroke();
  g.beginPath(); g.moveTo(300, 470); g.quadraticCurveTo(340, 440, 380, 465); g.stroke();
  g.fillStyle = '#7c7568'; g.fillRect(0, 478, 512, 34);
  g.fillStyle = '#6a6357'; g.fillRect(0, 498, 512, 14);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}
const muralTex = makeMuralTexture();

/* ── Photo slab: deep enough (0.5) that the oblique shear visibly tilts it ── */
const slab = new THREE.Mesh(
  new THREE.BoxGeometry(W, H, SLAB_D),
  new THREE.MeshBasicMaterial({ color: 0x8a8984 })
);
slab.position.z = SLAB_D / 2 - 0.02;
scene.add(slab);

const tileGroup = new THREE.Group();
const lineGroup = new THREE.Group();
const overlayGroup = new THREE.Group();
scene.add(tileGroup, lineGroup, overlayGroup);
let tiles = [];

function clearGroup(gr) {
  while (gr.children.length) {
    const o = gr.children.pop();
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
    else o.material?.dispose?.();
  }
}

function makeTile(x0, x1, y0, y1) {
  const w = (x1 - x0) - GAP, h = (y1 - y0) - GAP;
  if (w <= 0.005 || h <= 0.005) return;
  const geo = new THREE.PlaneGeometry(w, h);
  const uv = geo.attributes.uv;
  const u0 = (x0 + W / 2) / W, u1 = (x1 + W / 2) / W;
  const v0 = (y0 + H / 2) / H, v1 = (y1 + H / 2) / H;
  for (let i = 0; i < uv.count; i++) {
    uv.setXY(i, u0 + uv.getX(i) * (u1 - u0), v0 + uv.getY(i) * (v1 - v0));
  }
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ map: muralTex }));
  m.position.set((x0 + x1) / 2, (y0 + y1) / 2, ZTILE);
  m.userData.bounds = { x0, x1, y0, y1 };
  tileGroup.add(m);
  tiles.push(m);
}

function addStrip(x, y, w, h, color, z) {
  const s = new THREE.Mesh(new THREE.BoxGeometry(w, h, 0.015),
    new THREE.MeshBasicMaterial({ color }));
  s.position.set(x, y, z);
  lineGroup.add(s);
}

function buildGrid() {
  clearGroup(tileGroup); clearGroup(lineGroup); clearGroup(overlayGroup);
  tiles = [];
  if (plainMode) {
    // Panel a): original image, single tile, no grid lines
    makeTile(-W / 2, W / 2, -H / 2, H / 2);
    updateLabel();
    return;
  }
  const s = W / N;
  let edges;
  if (offsetMode) {
    edges = [-W / 2];
    for (let k = 1; k <= N; k++) edges.push(-W / 2 + (k - 0.5) * s);
    edges.push(W / 2);
  } else {
    edges = [];
    for (let i = 0; i <= N; i++) edges.push(-W / 2 + i * s);
  }
  const edgesY = edges.map(x => x * (H / W));
  for (let i = 0; i < edges.length - 1; i++)
    for (let j = 0; j < edgesY.length - 1; j++)
      makeTile(edges[i], edges[i + 1], edgesY[j], edgesY[j + 1]);
  const t = 0.02;
  for (let i = 1; i < edges.length - 1; i++)
    addStrip(edges[i], 0, t, H, 0x111111, ZLINE);
  for (let j = 1; j < edgesY.length - 1; j++)
    addStrip(0, edgesY[j], W, t, 0x111111, ZLINE);
  addStrip(0, H / 2, W, t, 0x111111, ZLINE);
  addStrip(0, -H / 2, W, t, 0x111111, ZLINE);
  addStrip(-W / 2, 0, t, H, 0x111111, ZLINE);
  addStrip(W / 2, 0, t, H, 0x111111, ZLINE);
  updateLabel();
}

/* ── Panel label ── */
const panelLabel = addLabel('', new THREE.Vector3(0, -H / 2 - 0.45, 0), { fontSize: '16px', bold: true });
function updateLabel() {
  if (plainMode) { panelLabel.div.textContent = 'Original image'; return; }
  panelLabel.div.textContent = `${N}×${N}${offsetMode ? ' offset' : ''} window${N > 1 ? 's' : ''}`;
}

/* ── Click → self-attention overlay within one window ── */
function showAttention(tile) {
  clearGroup(overlayGroup);
  if (plainMode) {
    showPopup('Original image', 'Panel a) is the unpartitioned reference. Choose a demo step or move the slider to cut the photo into attention windows.');
    return;
  }
  const { x0, x1, y0, y1 } = tile.userData.bounds;
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2, w = x1 - x0, h = y1 - y0;
  // dim all other tiles to emphasize locality
  const dim = new THREE.Mesh(new THREE.PlaneGeometry(W, H),
    new THREE.MeshBasicMaterial({ color: 0x666666, transparent: true, opacity: 0.45 }));
