}

function buildGrid() {
  clearGroup(tileGroup); clearGroup(lineGroup); clearGroup(overlayGroup);
  tiles = [];
  if (plainMode) {
    // Panel a): original image, single tile, no grid lines
    makeTile(-W / 2, W / 2, -H / 2, H / 2);
    updateLabel();
    return;
  }
  const s = W / N;
  let edges;
  if (offsetMode) {
    edges = [-W / 2];
    for (let k = 1; k <= N; k++) edges.push(-W / 2 + (k - 0.5) * s);
    edges.push(W / 2);
  } else {
    edges = [];
    for (let i = 0; i <= N; i++) edges.push(-W / 2 + i * s);
  }
  const edgesY = edges.map(x => x * (H / W));
  for (let i = 0; i < edges.length - 1; i++)
    for (let j = 0; j < edgesY.length - 1; j++)
      makeTile(edges[i], edges[i + 1], edgesY[j], edgesY[j + 1]);
  const t = 0.02;
  for (let i = 1; i < edges.length - 1; i++)
    addStrip(edges[i], 0, t, H, 0x111111, ZLINE);
  for (let j = 1; j < edgesY.length - 1; j++)
    addStrip(0, edgesY[j], W, t, 0x111111, ZLINE);
  addStrip(0, H / 2, W, t, 0x111111, ZLINE);
  addStrip(0, -H / 2, W, t, 0x111111, ZLINE);
  addStrip(-W / 2, 0, t, H, 0x111111, ZLINE);
  addStrip(W / 2, 0, t, H, 0x111111, ZLINE);
  updateLabel();
}

/* ── Panel label ── */
const panelLabel = addLabel('', new THREE.Vector3(0, -H / 2 - 0.45, 0), { fontSize: '16px', bold: true });
function updateLabel() {
  if (plainMode) { panelLabel.div.textContent = 'Original image'; return; }
  panelLabel.div.textContent = `${N}×${N}${offsetMode ? ' offset' : ''} window${N > 1 ? 's' : ''}`;
}

/* ── Click → self-attention overlay within one window ── */
function showAttention(tile) {
  clearGroup(overlayGroup);
  if (plainMode) {
    showPopup('Original image', 'Panel a) is the unpartitioned reference. Choose a demo step or move the slider to cut the photo into attention windows.');
    return;
  }
  const { x0, x1, y0, y1 } = tile.userData.bounds;
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2, w = x1 - x0, h = y1 - y0;
  // dim all other tiles to emphasize locality
  const dim = new THREE.Mesh(new THREE.PlaneGeometry(W, H),
    new THREE.MeshBasicMaterial({ color: 0x666666, transparent: true, opacity: 0.45 }));
  dim.position.set(0, 0, ZLINE + 0.005);
  overlayGroup.add(dim);
  // highlight fill + orange border
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(w - GAP, h - GAP),
    new THREE.MeshBasicMaterial({ color: 0xff8800, transparent: true, opacity: 0.25 }));
  fill.position.set(cx, cy, ZLINE + 0.01);
  overlayGroup.add(fill);
  const bt = 0.03, bz = ZLINE + 0.02;
  [[cx, y0 + bt / 2, w, bt], [cx, y1 - bt / 2, w, bt], [x0 + bt / 2, cy, bt, h], [x1 - bt / 2, cy, bt, h]]
    .forEach(([x, y, bw, bh]) => {
      const b = new THREE.Mesh(new THREE.BoxGeometry(bw, bh, 0.01),
        new THREE.MeshBasicMaterial({ color: 0xff8800 }));
      b.position.set(x, y, bz);
      overlayGroup.add(b);
    });
  const pts = [];
  for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) {
    const px = x0 + w * (0.15 + 0.7 * i / 3), py = y0 + h * (0.15 + 0.7 * j / 3);
    pts.push(new THREE.Vector3(px, py, ZLINE + 0.04));
    const dot = new THREE.Mesh(new THREE.CircleGeometry(0.035, 16),
      new THREE.MeshBasicMaterial({ color: 0x1a3366 }));
    dot.position.copy(pts[pts.length - 1]);
    overlayGroup.add(dot);
  }
  const lp = [];
  for (let i = 0; i < pts.length; i++)
    for (let j = i + 1; j < pts.length; j++)
      lp.push(pts[i].x, pts[i].y, ZLINE + 0.03, pts[j].x, pts[j].y, ZLINE + 0.03);
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(lp, 3));
  overlayGroup.add(new THREE.LineSegments(lg,
    new THREE.LineBasicMaterial({ color: 0x3366cc, transparent: true, opacity: 0.35 })));
  showPopup('Windowed self-attention',
    `Every token inside this ${N}×${N}${offsetMode ? ' offset' : ''} window attends to every other token in the SAME window — and to none outside it (neighbors are dimmed). Cost scales with window size, not image size. Alternate regular/offset partitions across layers to let information cross the boundaries.`);
}

const clickRay = new THREE.Raycaster();
const clickPtr = new THREE.Vector2();
canvas.addEventListener('click', (e) => {
  const r = canvas.getBoundingClientRect();
  clickPtr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  clickPtr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  clickRay.setFromCamera(clickPtr, camera);
  const hits = clickRay.intersectObjects(tiles, false);
  if (hits.length) showAttention(hits[0].object);
});

/* ── Controls ── */
const slider = document.getElementById('windowSize');
const nVal = document.getElementById('nVal');
const btnR = document.getElementById('btnRegular');
const btnO = document.getElementById('btnOffset');
function syncUI() {
  slider.value = N; nVal.textContent = N;
  btnR.classList.toggle('active', !offsetMode);
  btnO.classList.toggle('active', offsetMode);
}
function userEdit() { plainMode = false; }
slider.addEventListener('input', () => { N = +slider.value; userEdit(); syncUI(); buildGrid(); });
btnR.addEventListener('click', () => { offsetMode = false; userEdit(); syncUI(); buildGrid(); });
btnO.addEventListener('click', () => { offsetMode = true; userEdit(); syncUI(); buildGrid(); });

const STEPS = [
  { N: 4, off: false, plain: true },   // a) Original image
  { N: 4, off: false, plain: false },  // b) 4×4 windows
  { N: 4, off: true,  plain: false },  // c) 4×4 offset windows
  { N: 2, off: false, plain: false },  // d) 2×2 windows
  { N: 2, off: true,  plain: false },  // e) 2×2 offset windows
  { N: 1, off: false, plain: false },  // f) 1×1 window
];
function goToStep(i) {
  const s = STEPS[i];
  N = s.N; offsetMode = s.off; plainMode = s.plain;
  syncUI(); buildGrid();
}
document.querySelectorAll('#ui [data-step]').forEach(b =>
  b.addEventListener('click', () => goToStep(+b.dataset.step)));

/* ── Build + camera ── */
buildGrid();
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.7 });
// @FIGURE_CODE_END

