// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// photo base      → BoxGeometry(4.5, 4.5, 0.9) grey slab; deep enough that the oblique shear shows a clearly tilted parallelogram edge
// mural tiles     → PlaneGeometry per window, CanvasTexture (stylized graffiti, noisy), sub-UVs, white gaps
// grid lines      → thin black Box strips (0.012) raised above tile surface; square tiles via per-axis N
// clicked tile    → translucent orange plane + orange border strips
// tokens          → 4×4 dark-blue CircleGeometry dots inside clicked tile
// attention lines → LineSegments, semi-transparent blue, all token pairs within tile
// dimmed others   → translucent grey plane over non-selected tiles
// panel label     → addLabel centered below plane, includes panel letter a)–f)

const W = 4.5, H = 4.5, GAP = 0.03, ZLINE = 0.94, ZTILE = 0.90, SLAB_D = 0.9;
let N = 4, offsetMode = false, plainMode = false;
let currentStep = 1; // start on panel b

/* ── Stylized graffiti mural texture (noisy, varied palette) ── */
function makeMuralTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 512;
  const g = c.getContext('2d');
  // weathered concrete base with vertical streaks
  const grad = g.createLinearGradient(0, 0, 0, 512);
  grad.addColorStop(0, '#9a998f'); grad.addColorStop(0.6, '#8f8e86'); grad.addColorStop(1, '#7d7c73');
  g.fillStyle = grad; g.fillRect(0, 0, 512, 512);
  // photographic noise
  for (let i = 0; i < 4200; i++) {
    const v = 90 + Math.random() * 90 | 0;
    g.fillStyle = `rgba(${v},${v},${v - 6},${0.05 + Math.random() * 0.10})`;
    g.fillRect(Math.random() * 512, Math.random() * 512, 1 + Math.random() * 3, 1 + Math.random() * 3);
  }
  // concrete streaks / stains
  for (let i = 0; i < 26; i++) {
    g.fillStyle = `rgba(${70 + Math.random() * 40 | 0},${70 + Math.random() * 40 | 0},${66 + Math.random() * 30 | 0},0.10)`;
    const sx = Math.random() * 512;
    g.fillRect(sx, Math.random() * 300, 4 + Math.random() * 10, 60 + Math.random() * 180);
  }
  // ivy / foliage strip along the top
  g.fillStyle = '#4c4c40'; g.fillRect(0, 0, 512, 30);
  for (let i = 0; i < 140; i++) {
    g.fillStyle = ['#6f8a34', '#7fa03c', '#5c7a28', '#8aa845', '#a5b84e'][i % 5];
    g.fillRect(Math.random() * 512, Math.random() * 24, 4 + Math.random() * 12, 2 + Math.random() * 5);
  }
  // paint splatters in varied graffiti colors
  const splatCols = ['rgba(150,60,140,0.6)', 'rgba(90,60,130,0.55)', 'rgba(200,80,120,0.55)',
    'rgba(60,90,140,0.5)', 'rgba(40,140,150,0.5)', 'rgba(220,60,80,0.55)', 'rgba(30,30,40,0.5)'];
  for (let i = 0; i < 60; i++) {
    g.fillStyle = splatCols[i % splatCols.length];
    const sx = 280 + Math.random() * 230, sy = 30 + Math.random() * 330, r = 1.5 + Math.random() * 8;
    g.beginPath(); g.arc(sx, sy, r, 0, 7); g.fill();
    if (Math.random() < 0.4) { g.beginPath(); g.arc(sx + r * 1.6, sy + r * 1.2, r * 0.35, 0, 7); g.fill(); }
  }
  for (let i = 0; i < 18; i++) {
    g.fillStyle = splatCols[(i + 3) % splatCols.length];
    g.beginPath(); g.arc(Math.random() * 130, 60 + Math.random() * 380, 1.5 + Math.random() * 6, 0, 7); g.fill();
  }
  // teal swooshes
  g.strokeStyle = '#2a9aa0'; g.lineWidth = 4; g.lineCap = 'round';
  g.beginPath(); g.moveTo(430, 60); g.quadraticCurveTo(472, 92, 446, 132); g.stroke();
  g.beginPath(); g.moveTo(300, 472); g.quadraticCurveTo(340, 442, 380, 466); g.stroke();
  g.strokeStyle = '#3aaab0'; g.lineWidth = 3;
  g.beginPath(); g.moveTo(420, 400); g.quadraticCurveTo(460, 420, 470, 380); g.stroke();
  // girl: black bob hair
  g.fillStyle = '#1c1c1e';
  g.beginPath(); g.ellipse(200, 190, 74, 94, 0, 0, 7); g.fill();
  // face
  g.fillStyle = '#e89ab4';
  g.beginPath(); g.ellipse(205, 202, 46, 56, 0, 0, 7); g.fill();
  // fringe
  g.fillStyle = '#1c1c1e';
  g.beginPath(); g.ellipse(200, 158, 52, 30, 0, Math.PI, 0); g.fill();
  // glasses + smile
  g.strokeStyle = '#222'; g.lineWidth = 3;
  g.strokeRect(176, 190, 24, 17); g.strokeRect(212, 190, 24, 17);
  g.beginPath(); g.moveTo(200, 198); g.lineTo(212, 198); g.stroke();
  g.beginPath(); g.arc(206, 224, 12, 0.2, Math.PI - 0.2); g.stroke();
  // blush
  g.fillStyle = 'rgba(220,110,140,0.5)';
  g.beginPath(); g.arc(180, 218, 6, 0, 7); g.fill();
  g.beginPath(); g.arc(232, 218, 6, 0, 7); g.fill();
  // yellow hoodie
  g.fillStyle = '#e8c81e';
  g.beginPath();
  g.moveTo(138, 302); g.quadraticCurveTo(205, 258, 272, 302);
  g.lineTo(288, 464); g.lineTo(122, 464); g.closePath(); g.fill();
  g.strokeStyle = '#b89a10'; g.lineWidth = 3; g.stroke();
  g.fillStyle = '#d8b812';
  g.beginPath(); g.ellipse(205, 285, 46, 20, 0, 0, 7); g.fill();
  g.fillStyle = '#333';
  g.beginPath(); g.moveTo(196, 300); g.lineTo(214, 300); g.lineTo(205, 313); g.closePath(); g.fill();
  // hoodie shading
  g.fillStyle = 'rgba(160,130,10,0.35)';
  g.fillRect(250, 320, 30, 140); g.fillRect(140, 340, 18, 110);
  // left sign 'FOR ALL KIDS'
  g.save(); g.translate(70, 330); g.rotate(-0.12);
  g.fillStyle = '#f2f0ea'; g.fillRect(-55, -80, 100, 150);
  g.strokeStyle = '#888'; g.lineWidth = 2; g.strokeRect(-55, -80, 100, 150);
  g.fillStyle = 'rgba(0,0,0,0.06)'; g.fillRect(-55, 40, 100, 30);
  g.strokeStyle = '#c02030'; g.lineWidth = 3; g.lineCap = 'round';
  for (let r = 0; r < 4; r++) {
    g.beginPath();
    let x = -45, y = -60 + r * 32;
    g.moveTo(x, y);
    while (x < 35) { x += 8 + Math.random() * 8; g.lineTo(x, y + (Math.random() * 14 - 7)); }
    g.stroke();
  }
  g.restore();
  // right sign 'GIVE PEACE A CHANCE'
  g.save(); g.translate(392, 208); g.rotate(0.10);
  g.fillStyle = '#f2f0ea'; g.fillRect(-70, -90, 132, 172);
  g.strokeStyle = '#888'; g.lineWidth = 2; g.strokeRect(-70, -90, 132, 172);
  g.fillStyle = 'rgba(0,0,0,0.06)'; g.fillRect(-70, 52, 132, 30);
  g.strokeStyle = '#c02030'; g.lineWidth = 3; g.lineCap = 'round';
  for (let r = 0; r < 5; r++) {
    g.beginPath();
    let x = -58, y = -70 + r * 32;
    g.moveTo(x, y);
    while (x < 48) { x += 8 + Math.random() * 8; g.lineTo(x, y + (Math.random() * 14 - 7)); }
    g.stroke();
  }
  g.restore();
  // red hearts + tag scribbles
  function heart(x, y, s) {
    g.fillStyle = '#c02535';
    g.beginPath();
    g.moveTo(x, y + s);
    g.bezierCurveTo(x - s * 1.4, y, x - s * 0.7, y - s, x, y - s * 0.3);
    g.bezierCurveTo(x + s * 0.7, y - s, x + s * 1.4, y, x, y + s);
    g.fill();
  }
  heart(60, 118, 16); heart(455, 332, 14); heart(330, 430, 12); heart(120, 480, 10);
  g.strokeStyle = '#c02535'; g.lineWidth = 3;
  g.beginPath(); g.moveTo(30, 200); g.quadraticCurveTo(60, 180, 80, 210); g.quadraticCurveTo(95, 230, 70, 240); g.stroke();
  g.strokeStyle = '#7a3a8a'; g.lineWidth = 3;
  g.beginPath(); g.moveTo(480, 160); g.quadraticCurveTo(495, 200, 475, 240); g.stroke();
  // pavement strip at the bottom
  g.fillStyle = '#7c7568'; g.fillRect(0, 478, 512, 34);
  g.fillStyle = '#6a6357'; g.fillRect(0, 498, 512, 14);
  for (let i = 0; i < 200; i++) {
    g.fillStyle = `rgba(${50 + Math.random() * 40 | 0},${48 + Math.random() * 36 | 0},${42 + Math.random() * 30 | 0},0.25)`;
    g.fillRect(Math.random() * 512, 478 + Math.random() * 32, 1 + Math.random() * 3, 1 + Math.random() * 2);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}
const muralTex = makeMuralTexture();

/* ── Photo slab: 0.9 deep so the oblique shear reads as a tilted parallelogram ── */
const slab = new THREE.Mesh(
  new THREE.BoxGeometry(W, H, SLAB_D),
  new THREE.MeshBasicMaterial({ color: 0x8a8984 })
);
slab.position.z = SLAB_D / 2 - 0.02;
scene.add(slab);

const tileGroup = new THREE.Group();
const lineGroup = new THREE.Group();
const overlayGroup = new THREE.Group();
scene.add(tileGroup, lineGroup, overlayGroup);
let tiles = [];

function clearGroup(gr) {
  while (gr.children.length) {
    const o = gr.children.pop();
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
    else o.material?.dispose?.();
  }
}

function makeTile(x0, x1, y0, y1) {
  const w = (x1 - x0) - GAP, h = (y1 - y0) - GAP;
  if (w <= 0.005 || h <= 0.005) return;
  const geo = new THREE.PlaneGeometry(w, h);
  const uv = geo.attributes.uv;
  const u0 = (x0 + W / 2) / W, u1 = (x1 + W / 2) / W;
  const v0 = (y0 + H / 2) / H, v1 = (y1 + H / 2) / H;
  for (let i = 0; i < uv.count; i++) {
    uv.setXY(i, u0 + uv.getX(i) * (u1 - u0), v0 + uv.getY(i) * (v1 - v0));
  }
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ map: muralTex }));
  m.position.set((x0 + x1) / 2, (y0 + y1) / 2, ZTILE);
  m.userData.bounds = { x0, x1, y0, y1 };
  tileGroup.add(m);
  tiles.push(m);
}

function addStrip(x, y, w, h, color, z) {
  const s = new THREE.Mesh(new THREE.BoxGeometry(w, h, 0.012),
    new THREE.MeshBasicMaterial({ color }));
  s.position.set(x, y, z);
  lineGroup.add(s);
}

function buildGrid() {
  clearGroup(tileGroup); clearGroup(lineGroup); clearGroup(overlayGroup);
  tiles = [];
  if (plainMode) {
    makeTile(-W / 2, W / 2, -H / 2, H / 2);
    updateLabel();
    return;
  }
  // square slab (W === H) with N divisions per axis → square tiles
  let edges;
  if (offsetMode) {
    const s = W / N;
    edges = [-W / 2];
    for (let k = 1; k <= N; k++) edges.push(-W / 2 + (k - 0.5) * s);
    edges.push(W / 2);
  } else {
    edges = [];
    for (let i = 0; i <= N; i++) edges.push(-W / 2 + i * W / N);
  }
  const edgesY = edges.slice();
  for (let i = 0; i < edges.length - 1; i++)
    for (let j = 0; j < edgesY.length - 1; j++)
      makeTile(edges[i], edges[i + 1], edgesY[j], edgesY[j + 1]);
  const t = 0.012;
  for (let i = 1; i < edges.length - 1; i++)
    addStrip(edges[i], 0, t, H, 0x111111, ZLINE);
  for (let j = 1; j < edgesY.length - 1; j++)
    addStrip(0, edgesY[j], W, t, 0x111111, ZLINE);
  addStrip(0, H / 2, W, t, 0x111111, ZLINE);
  addStrip(0, -H / 2, W, t, 0x111111, ZLINE);
  addStrip(-W / 2, 0, t, H, 0x111111, ZLINE);
  addStrip(W / 2, 0, t, H, 0x111111, ZLINE);
  updateLabel();
}

/* ── Panel label: letter + caption, mirroring the source annotations ── */
const LETTERS = ['a', 'b', 'c', 'd', 'e', 'f'];
const panelLabel = addLabel('', new THREE.Vector3(0, -H / 2 - 0.42, 0), { fontSize: '16px', bold: true });
function updateLabel() {
  const letter = LETTERS[currentStep] ? LETTERS[currentStep] + ') ' : '';
  if (plainMode) { panelLabel.div.textContent = letter + 'Original image'; return; }
  panelLabel.div.textContent = `${letter}${N}×${N}${offsetMode ? ' offset' : ''} window${N > 1 ? 's' : ''}`;
}

/* ── Click → self-attention overlay within one window ── */
function showAttention(tile) {
  clearGroup(overlayGroup);
  if (plainMode) {
    showPopup('Original image', 'Panel a) is the unpartitioned reference. Choose a demo step or move the slider to cut the photo into attention windows.');
    return;
  }
  const { x0, x1, y0, y1 } = tile.userData.bounds;
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2, w = x1 - x0, h = y1 - y0;
  const dim = new THREE.Mesh(new THREE.PlaneGeometry(W, H),
    new THREE.MeshBasicMaterial({ color: 0x666666, transparent: true, opacity: 0.45 }));
  dim.position.set(0, 0, ZLINE + 0.005);
  overlayGroup.add(dim);
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(w - GAP, h - GAP),
    new THREE.MeshBasicMaterial({ color: 0xff8800, transparent: true, opacity: 0.25 }));
  fill.position.set(cx, cy, ZLINE + 0.01);
  overlayGroup.add(fill);
  const bt = 0.03, bz = ZLINE + 0.02;
  [[cx, y0 + bt / 2, w, bt], [cx, y1 - bt / 2, w, bt], [x0 + bt / 2, cy, bt, h], [x1 - bt / 2, cy, bt, h]]
    .forEach(([x, y, bw, bh]) => {
      const b = new THREE.Mesh(new THREE.BoxGeometry(bw, bh, 0.01),
        new THREE.MeshBasicMaterial({ color: 0xff8800 }));
      b.position.set(x, y, bz);
      overlayGroup.add(b);
    });
  const pts = [];
  for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) {
    const px = x0 + w * (0.15 + 0.7 * i / 3), py = y0 + h * (0.15 + 0.7 * j / 3);
    pts.push(new THREE.Vector3(px, py, ZLINE + 0.04));
    const dot = new THREE.Mesh(new THREE.CircleGeometry(0.035, 16),
      new THREE.MeshBasicMaterial({ color: 0x1a3366 }));
    dot.position.copy(pts[pts.length - 1]);
    overlayGroup.add(dot);
  }
  const lp = [];
  for (let i = 0; i < pts.length; i++)
    for (let j = i + 1; j < pts.length; j++)
      lp.push(pts[i].x, pts[i].y, ZLINE + 0.03, pts[j].x, pts[j].y, ZLINE + 0.03);
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(lp, 3));
  overlayGroup.add(new THREE.LineSegments(lg,
    new THREE.LineBasicMaterial({ color: 0x3366cc, transparent: true, opacity: 0.35 })));
  showPopup('Windowed self-attention',
    `Every token inside this ${N}×${N}${offsetMode ? ' offset' : ''} window attends to every other token in the SAME window — and to none outside it (neighbors are dimmed). Cost scales with window size, not image size. Alternate regular/offset partitions across layers to let information cross the boundaries.`);
}

const clickRay = new THREE.Raycaster();
const clickPtr = new THREE.Vector2();
canvas.addEventListener('click', (e) => {
  const r = canvas.getBoundingClientRect();
  clickPtr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  clickPtr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  clickRay.setFromCamera(clickPtr, camera);
  const hits = clickRay.intersectObjects(tiles, false);
  if (hits.length) showAttention(hits[0].object);
});

/* ── Controls ── */
const slider = document.getElementById('windowSize');
const nVal = document.getElementById('nVal');
const btnR = document.getElementById('btnRegular');
const btnO = document.getElementById('btnOffset');
function syncUI() {
  slider.value = N; nVal.textContent = N;
  btnR.classList.toggle('active', !offsetMode);
  btnO.classList.toggle('active', offsetMode);
}
function userEdit() { plainMode = false; currentStep = -1; }
slider.addEventListener('input', () => { N = +slider.value; userEdit(); syncUI(); buildGrid(); });
btnR.addEventListener('click', () => { offsetMode = false; userEdit(); syncUI(); buildGrid(); });
btnO.addEventListener('click', () => { offsetMode = true; userEdit(); syncUI(); buildGrid(); });

const STEPS = [
  { N: 4, off: false, plain: true },   // a) Original image
  { N: 4, off: false, plain: false },  // b) 4×4 windows
  { N: 4, off: true,  plain: false },  // c) 4×4 offset windows
  { N: 2, off: false, plain: false },  // d) 2×2 windows
  { N: 2, off: true,  plain: false },  // e) 2×2 offset windows
  { N: 1, off: false, plain: false },  // f) 1×1 window
];
function goToStep(i) {
  const s = STEPS[i];
  N = s.N; offsetMode = s.off; plainMode = s.plain;
  currentStep = i;
  syncUI(); buildGrid();
}
document.querySelectorAll('#ui [data-step]').forEach(b =>
  b.addEventListener('click', () => goToStep(+b.dataset.step)));

/* ── Build + camera ── */
buildGrid();
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.7 });
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

